import{_ as t,o as i,c as r,a4 as n}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse('{"title":"ADR-0005 — Positionnement marché","description":"Extrait de docs/adr/0005-positionnement-marche.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0005 — Positionnement marché","description":"Extrait de docs/adr/0005-positionnement-marche.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0005-positionnement-marche.md","filePath":"developpeurs/adr/0005-positionnement-marche.md"}'),s={name:"developpeurs/adr/0005-positionnement-marche.md"};function a(o,e,l,c,u,d){return i(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0005--positionnement-marché" tabindex="-1">ADR-0005 — Positionnement marché <a class="header-anchor" href="#adr-0005--positionnement-marché" aria-label="Permalink to &quot;ADR-0005 — Positionnement marché {#adr-0005--positionnement-marché}&quot;">​</a></h1><p><strong>Date :</strong> 19 août 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> CDC_CMS_AI_Native_v1.1 §17 point ouvert #5 ; plan d&#39;action agile §3.1.bis</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Le CDC signale que le corpus oriente fortement vers la collectivité territoriale française — un marché réel avec des besoins précis — mais que si le produit se spécialise entièrement sur ce segment, le positionnement « CMS + Page Builder + Application Platform + AI Engine » de la v1.0 devient trompeur. Le CDC pose la question sans la trancher : <em>« Choisir : produit généraliste avec une verticale publique, ou produit pour le secteur public. Ce n&#39;est pas la même feuille de route. »</em></p><p>Cette décision a un effet direct sur ADR-0002 (frontière Core/plugin) : un positionnement « pur secteur public » aurait justifié d&#39;intégrer nativement au Core des éléments comme les chiffres-clés ou PayFiP ; un positionnement généraliste les repousse en plugins par défaut.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p>Le produit est positionné comme un <strong>CMS généraliste avec une verticale publique forte</strong> : CMS + Page Builder + Application Platform + AI Engine pour tout usage, avec un pack « secteur public FR » (PayFiP, SVE, co-marquage, blocs institutionnels) mis en avant comme différenciateur grâce à la richesse du corpus — sans que ce pack ne détermine l&#39;architecture du Core.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Produit dédié secteur public français</strong></td><td>Message plus clair, feuille de route entièrement pilotée par les besoins des collectivités territoriales. Écartée car elle réduirait le marché adressable dès le départ et contredirait le principe API-first / plateforme généraliste conservé de la v1.0 (§0.2 du CDC).</td></tr><tr><td><strong>Reporter la décision</strong></td><td>Écartée : le CDC signale explicitement que ce choix détermine la feuille de route ; le reporter aurait laissé plusieurs sprints (notamment E1/E2) se dérouler sans direction claire sur ce qui doit rester générique.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Cohérent avec ADR-0002 : le Core reste petit et générique, la richesse du corpus est exploitée comme bibliothèque de plugins « secteur public FR », pas comme spécification du Core.</li><li>Marché adressable plus large qu&#39;un positionnement pur secteur public, sans renoncer à l&#39;avantage concurrentiel que représente le corpus sur ce segment.</li><li>Le message produit reste honnête : le CDC lui-même liste les items hors périmètre commercial explicite (PayFiP, co-marquage) comme des preuves d&#39;intérêt pour un marketplace régionalisé, pas comme des fonctionnalités cœur.</li></ul><p><strong>Négatives</strong></p><ul><li>Positionnement plus difficile à communiquer qu&#39;un message mono-marché (« le CMS des collectivités ») — nécessite un discours à deux niveaux (plateforme généraliste / pack vertical).</li><li>Risque de dilution si le pack « secteur public FR » n&#39;est pas maintenu au même niveau de qualité que le Core au fil du temps — à surveiller en priorisation de backlog.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Documenter le pack « secteur public FR » comme un ensemble de plugins nommé, pas comme une simple liste éparse dans le backlog (cohérence avec ADR-0002) — fait le 14 septembre 2026 par l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0028-packs-verticaux-du-catalogue-livre">ADR-0028</a>, qui nomme les cinq packs du catalogue livré et exerce pour la première fois la moitié généraliste de la présente décision.</li><li>[ ] Revoir ce positionnement une fois un premier retour marché disponible (aucune échéance fixée — à replacer dans le comité mensuel des points ouverts, §8 du plan d&#39;action).</li></ul>',16)])])}const h=t(s,[["render",a]]);export{m as __pageData,h as default};
